INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES
(90015, 10, 0, 0, 0, 0, 0, 0, 0, 'AHH! ME LEG!!  Oh it fits just like I remember. Though I think I can buff out these teeth marks.', 0),
(90020, 0, 0, 0, 0, 0, 0, 0, 0, 'Well look at that... you caught a big one!  Looks like that will fetch a nice price on the market.', 12340),
(90021, 5, 1, 0, 0, 0, 0, 0, 0, 'What a mean little creature!  I''m sure these will make something tasty. $b$bI''m just kidding, of course.$b$b', 12340),
(90022, 0, 0, 0, 0, 0, 0, 0, 0, '$b$bTo be completely honest, I thought it would be more of a challenge for you.', 12340),
(90005, 10, 0, 0, 0, 0, 0, 0, 0, 'You got all those pesky mice $N!? Fantastic! I found this one earlier and he seems friendly, just careful he bites!', 0),
(90007, 10, 0, 0, 0, 0, 0, 0, 0, 'Thank you for the help! Please enjoy some of my delicious produce!', 0),
(90024, 4, 0, 0, 0, 0, 0, 0, 0, 'My prized cow is back!! Thank you adventurer I greatly appreciate your assistance in this matter!', 0),
(90008, 10, 0, 0, 0, 0, 0, 0, 0, 'I *hiccup* knew it....here ya go! Drunk Gordy is never wrong!', 0),
(90010, 10, 0, 0, 0, 0, 0, 0, 0, 'Thank you brave warrior! Now that the invaders have no commander their activity should die down. The residents of Moraz Island thank you! Please take these gifts as a token of our gratitude. ', 0),
(90025, 4, 0, 0, 0, 0, 0, 0, 0, 'Oh Hell Yeah!  Now can keep rocking out! Uh....thanks...here', 0),
(90026, 4, 0, 0, 0, 0, 0, 0, 0, 'Yes, this shoulds dos. I''m feelings prettys goods nows. Here takes this, its always going out of tunes..crappys guitars.', 0),
(90009, 10, 0, 0, 0, 0, 0, 0, 0, 'My Precious!! Its mine again!!!', 0),
(90012, 10, 0, 0, 0, 0, 0, 0, 0, 'Thanks man.......Uh we dont have much but can you do one more favor for us? Snoochie-Boochie!', 0),
(90011, 10, 0, 0, 0, 0, 0, 0, 0, 'Thank you for the help! Here take this as a token of my appreciation.', 0),
(90006, 10, 0, 0, 0, 0, 0, 0, 0, 'Thank you for your help! The Citizens of Morza Island can finally breath a sigh of relief!', 0),
(90013, 4, 0, 0, 0, 0, 0, 0, 0, 'Thanks man! Uh..we do not have much but you can have one of these Snoochie Boochie items we "found"', 0);
