(90022, 0, 0, 'Tell me you caught some cuttlefish. Please tell me you caught those little buggers.', 12340),
(90005, 0, 0, 'Have you exterminated those pest yet!?', 0),
(90007, 0, 0, 'Have you gotten rid of those pieces of shit yet!?', 0),
(90024, 0, 0, 'Betsy hasn''t came home yet...I''m worried.', 0),
(90008, 0, 0, 'Didya...sees....i mean slay *hiccup* the beast!???', 0),
(90010, 0, 0, 'Have you dealt with those insolent Kobolds and their Commander?', 0),
(90025, 15, 0, 'Have you got the booze yet!?', 0),
(90026, 15, 0, 'Where is tha booze!???', 0),
(90009, 0, 0, 'That thiefs stoles it from us!!', 0),
(90011, 0, 0, 'Have you gotten rid of those rat looking bastards yet?', 0),
